/*
 * The order of the printable document: the sidebar from src/sidebar.mjs, with
 * autogenerated groups expanded the way Starlight does it (by `sidebar.order`,
 * then by path; subdirectories become subgroups named after the directory;
 * `sidebar.hidden` pages are left out).
 *
 * Starlight's computed sidebar (`Astro.locals.starlightRoute.sidebar`) is not
 * available yet when a custom page renders content entries, so it is rebuilt here.
 */
import { getCollection, type CollectionEntry } from 'astro:content';
import { sidebar } from '../../sidebar.mjs';

type Entry = CollectionEntry<'docs'>;
export type OutlineNode =
	| { type: 'group'; label: string; children: OutlineNode[] }
	| { type: 'page'; entry: Entry; path: string };

type ConfigItem =
	| { label: string; translations?: Record<string, string>; items: ConfigItem[] }
	| { autogenerate: { directory: string } }
	| { slug: string }
	| string;

const collator = new Intl.Collator('en');

interface Dir {
	name: string;
	slug: string;
	dirs: Map<string, Dir>;
	pages: Entry[];
}

const order = (entry: Entry) => entry.data.sidebar.order ?? Number.MAX_VALUE;
const dirOrder = (dir: Dir): number => Math.min(...dir.pages.map(order), ...[...dir.dirs.values()].map(dirOrder));

function sortedNodes(dir: Dir): OutlineNode[] {
	const nodes = [
		...[...dir.dirs.values()].map((sub) => ({ weight: dirOrder(sub), key: sub.slug, node: groupOf(sub) })),
		...dir.pages.map((entry) => ({ weight: order(entry), key: entry.id, node: pageOf(entry) })),
	];
	nodes.sort((a, b) => (a.weight !== b.weight ? a.weight - b.weight : collator.compare(a.key, b.key)));
	return nodes.map((n) => n.node);
}

const groupOf = (dir: Dir): OutlineNode => ({ type: 'group', label: dir.name, children: sortedNodes(dir) });
const pageOf = (entry: Entry): OutlineNode => ({ type: 'page', entry, path: `/${entry.id}/` });

export async function getOutline(lang: 'id' | 'en'): Promise<OutlineNode[]> {
	const prefix = lang === 'en' ? 'en/' : '';
	const entries = (await getCollection('docs')).filter(
		(entry) => (lang === 'en' ? entry.id.startsWith('en/') : !entry.id.startsWith('en/')) && !entry.data.sidebar.hidden,
	);

	function autogenerate(directory: string): OutlineNode[] {
		const root: Dir = { name: directory, slug: directory, dirs: new Map(), pages: [] };
		for (const entry of entries) {
			const id = entry.id.slice(prefix.length);
			if (id !== directory && !id.startsWith(`${directory}/`)) continue;
			// A file's directory parts below the autogenerated directory; `dir/index` sits in `dir`.
			const parts = id.slice(directory.length + 1).split('/').filter(Boolean).slice(0, -1);
			let dir = root;
			for (const part of parts) {
				const slug = `${dir.slug}/${part}`;
				if (!dir.dirs.has(part)) dir.dirs.set(part, { name: part, slug, dirs: new Map(), pages: [] });
				dir = dir.dirs.get(part)!;
			}
			dir.pages.push(entry);
		}
		return sortedNodes(root);
	}

	function expand(item: ConfigItem): OutlineNode[] {
		if (typeof item === 'string' || 'slug' in item) {
			const slug = typeof item === 'string' ? item : item.slug;
			const entry = entries.find((e) => e.id === `${prefix}${slug}`);
			return entry ? [pageOf(entry)] : [];
		}
		if ('autogenerate' in item) return autogenerate(item.autogenerate.directory);
		const label = (lang === 'en' && item.translations?.en) || item.label;
		return [{ type: 'group', label, children: item.items.flatMap(expand) }];
	}

	return (sidebar as ConfigItem[]).flatMap(expand);
}
